#!/usr/bin/env bash
# push-all smoke: temp repos with bare origins, a fake github remote and a stub
# publish.mjs behind a fake `bun`. Never touches the real code root or HOME.

for _a in "$@"; do case "$_a" in --help|-h)
	printf 'usage: %s %s\n' "${0##*/}" ''
	printf '%s\n' 'Hermetic regression tests for util/push-all.sh; takes no arguments.'
	exit 0;; esac; done
# >>> shguard modes=exec (generated by shell-disposition-gate --guard; do not edit)
case $(realpath -- "$0" 2>/dev/null) in */'util/tests/push-all.sh') _shguard_m='exec' ;; *) if [ "${SHGUARD_MODE-}" = 'pipe' ]; then _shguard_m='pipe'; else _shguard_m='source'; fi ;; esac
# shellcheck disable=SC2317
case $_shguard_m in
  exec) unset _shguard_m ;;
  *) printf '%s: refusing %s invocation (supports: exec; pipe callers set SHGUARD_MODE=pipe)\n' 'push-all.sh' "$_shguard_m" >&2; unset _shguard_m; return 1 2>/dev/null || exit 1 ;;
esac
# <<< shguard
_bid="$(dirname "$(readlink -f "${BASH_SOURCE[0]}")")/../lib/build-id.sh"
# shellcheck source=util/lib/build-id.sh
[ -r "$_bid" ] && { . "$_bid"; build_flags "${BASH_SOURCE[0]}" "$@"; }
set -u

test_dir=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
script="$test_dir/../push-all.sh"
helper="$test_dir/../lib/push.sh"
root=$(mktemp -d)
trap 'rm -rf "$root"' EXIT

export HOME="$root/home" GIT_CONFIG_GLOBAL=/dev/null GIT_CONFIG_SYSTEM=/dev/null
export GIT_AUTHOR_NAME=t GIT_AUTHOR_EMAIL=t@example.invalid GIT_COMMITTER_NAME=t GIT_COMMITTER_EMAIL=t@example.invalid
unset CLAUDECODE
for v in $(compgen -e CODEX_); do unset "$v"; done
mkdir -p "$HOME"

pass_count=0
fail_count=0
ok() { printf 'ok %d - %s\n' "$((pass_count + fail_count + 1))" "$1"; pass_count=$((pass_count + 1)); }
nok() { printf 'not ok %d - %s\n' "$((pass_count + fail_count + 1))" "$1" >&2; fail_count=$((fail_count + 1)); }
check() { # <description> <condition-rc>
	if [ "$2" -eq 0 ]; then ok "$1"; else nok "$1"; fi
}

# Fake `bun` runs the stub publish.mjs (a bash script) directly.
mkdir -p "$root/bin"
printf '#!/bin/bash\nexec bash "$@"\n' > "$root/bin/bun"
chmod +x "$root/bin/bun"
export PATH="$root/bin:$PATH"
calls="$root/project-calls"
: > "$calls"
cat > "$root/publish-stub.sh" <<'STUB'
#!/bin/bash
# stub publish.mjs: status | project | release --push, repo is the last argument
cmd=$1 r=${*: -1}
state="$r/.git/stub-projected"
case $cmd in
	status)
		[ -n "${STUB_STATUS_LOG:-}" ] && echo "$r" >> "$STUB_STATUS_LOG"
		[ -n "${STUB_GARBAGE:-}" ] && { echo 'not json {'; exit 0; }
		[ -n "${STUB_STATUS_FAIL:-}" ] && exit 1
		src=$(git -C "$r" rev-parse master)
		if [ -f "$state" ]; then
			proj=$(cat "$state")
			lag=$(git -C "$r" rev-list --count master "^$proj")
			projj="\"$proj\""
		else
			lag=null projj=null
		fi
		pt=$(git -C "$r" rev-parse -q --verify refs/heads/public || echo null)
		pu=$(git -C "$r" rev-parse -q --verify refs/remotes/github/master || echo null)
		q() { [ "$1" = null ] && printf null || printf '"%s"' "$1"; }
		tags() { local t out=; for t in $(echo "$2" | tr , " "); do out+="${out:+,}{\"tag\":\"$t\",\"reason\":\"$1\"}"; done; printf "%s" "$out"; }
		unproj=$STUB_UNPROJECTED unrel=$STUB_UNRELEASED
		[ -f "$r/.git/stub-tagsproj" ] && { unrel+=",$unproj"; unproj=; }
		[ -f "$r/.git/stub-released" ] && unrel=
		ul=$(tags unprojected "$unproj"; [ -n "$unproj" ] && [ -n "${unrel#,}" ] && printf ,; tags unreleased "${unrel#,}")
		printf '{\n  "manifest": {\n    "lagCommits": 99\n  },\n  "sourceTip": "%s",\n  "projectedSource": %s,\n  "publicTip": %s,\n  "publishedTip": %s,\n  "lagCommits": %s,\n  "unreleasedTags": [%s]\n}\n' \
			"$src" "$projj" "$(q "$pt")" "$(q "$pu")" "$lag" "$ul" ;;
	project)
		[ -n "${STUB_FAIL:-}" ] && { echo "scan: FAIL"; exit 1; }
		echo "$r" >> "$STUB_CALLS"
		git -C "$r" rev-parse master > "$state"
		[ -n "${STUB_UNPROJECTED:-}" ] && : > "$r/.git/stub-tagsproj"
		git -C "$r" branch -f public master ;;
	release)
		echo "$*" >> "$STUB_RELEASE_CALLS"
		[ -n "${STUB_RELEASE_FAIL:-}" ] && { echo "noise"; echo "release: no GitHub token" >&2; exit 1; }
		: > "$r/.git/stub-released"
		echo "released" ;;
esac
STUB
export STUB_CALLS="$calls"
export STUB_RELEASE_CALLS="$root/release-calls"
: > "$STUB_RELEASE_CALLS"
export STUB_UNPROJECTED='' STUB_UNRELEASED=''

commit() { git -C "$1" commit -q --allow-empty -m "$2"; }
# mkrepo <name> [initiative-file]: repo with INITIATIVE.md, bare origin, tracking master.
mkrepo() {
	local r="$root/code/$1"
	git init -q -b master "$r"
	[ "${2-INITIATIVE.md}" = - ] || : > "$r/${2-INITIATIVE.md}"
	git -C "$r" add -A
	commit "$r" base
	git init -q --bare -b master "$root/origins/$1.git"
	git -C "$r" remote add origin "$root/origins/$1.git"
	git -C "$r" push -q -u origin master
}
snap() { # all refs of every repo and bare remote
	for d in "$root"/code/*/ "$root"/origins/*.git "$root"/gh/*.git; do
		[ -d "$d" ] && { git -C "$d" for-each-ref; git -C "$d" rev-parse HEAD 2> /dev/null; }
	done
}
run() { PUSH_OUT=$(bash "$script" --root "$root/code" --publish-mjs "$root/publish-stub.sh" "$@" 2>&1); PUSH_RC=$?; }

mkrepo alpha
mkrepo beta INITIATIVE.md
mkrepo legacy DEVELOPMENT.md
mkrepo plain -                 # no INITIATIVE.md: out of scope
mkrepo pub
git init -q --bare -b master "$root/gh/pub.git"
git -C "$root/code/pub" remote add github "$root/gh/pub.git"
git -C "$root/code/pub" config remote.github.push refs/heads/public:refs/heads/master
echo '{}' > "$root/code/pub/.publication.json"
git init -q -b master "$root/code/noup"; : > "$root/code/noup/INITIATIVE.md"
git -C "$root/code/noup" add -A; commit "$root/code/noup" base
for r in alpha legacy plain pub; do commit "$root/code/$r" ahead1; done
commit "$root/code/alpha" ahead2
git -C "$root/code/beta" checkout -q -b side
commit "$root/code/beta" onside
git -C "$root/code/beta" checkout -q master
commit "$root/code/beta" onmaster
git -C "$root/code/beta" checkout -q side

# 1 status is read-only, lists in-scope repos, never projects
before=$(snap)
run
after=$(snap)
check 'status leaves every ref and remote unchanged' "$(if [ "$before" = "$after" ]; then echo 0; else echo 1; fi)"
check 'status never runs project' "$(if [ ! -s "$calls" ]; then echo 0; else echo 1; fi)"
check 'status exits 0 with final count' "$(if [ "$PUSH_RC" -eq 0 ] && [[ $PUSH_OUT == *'5 repos:'* ]]; then echo 0; else echo 1; fi)"
# 2 repo set
check 'non-initiative repo is skipped; legacy DEVELOPMENT.md counts' \
	"$(if [[ $PUSH_OUT != *plain:* && $PUSH_OUT == *legacy:\ origin\ +1* ]]; then echo 0; else echo 1; fi)"
# 3 no upstream: counted always, listed only with --verbose
check 'bare status hides the skipped repo but counts it' "$(if [[ $PUSH_OUT != *noup:* && $PUSH_OUT == *'1 skipped'* ]]; then echo 0; else echo 1; fi)"
run --verbose
check '--verbose lists the repo without upstream as skipped' "$(if [[ $PUSH_OUT == *'noup: skipped (master has no upstream)'* ]]; then echo 0; else echo 1; fi)"
check 'status reports projection lag without projecting' "$(if [[ $PUSH_OUT == *'pub: origin +1; projection lag null'* ]]; then echo 0; else echo 1; fi)"

# 4 refusal in an agent session
before=$(snap)
CLAUDECODE=1 run --push
check '--push refused under CLAUDECODE, nothing pushed' "$(if [ "$PUSH_RC" -eq 2 ] && [ "$before" = "$(snap)" ]; then echo 0; else echo 1; fi)"
CODEX_HOME=x run --push
check '--push refused under CODEX_*, nothing pushed' "$(if [ "$PUSH_RC" -eq 2 ] && [ "$before" = "$(snap)" ]; then echo 0; else echo 1; fi)"

# 5 --push pushes master of ahead repos (even with another branch checked out)
run --push
good=0
for r in alpha beta legacy pub; do
	[ "$(git -C "$root/code/$r" rev-parse master)" = "$(git -C "$root/origins/$r.git" rev-parse master)" ] || good=1
done
check '--push pushes master of every ahead repo, including off-master checkout' "$good"
check 'checked-out branch is left alone' "$(if [ "$(git -C "$root/code/beta" rev-parse --abbrev-ref HEAD)" = side ]; then echo 0; else echo 1; fi)"
# 6 projection only when lagging
check 'projection ran once for the lagging repo and was mirrored' \
	"$(if [ "$(wc -l < "$calls")" -eq 1 ] && [ "$(git -C "$root/code/pub" rev-parse public)" = "$(git -C "$root/gh/pub.git" rev-parse master)" ]; then echo 0; else echo 1; fi)"
run --push
check 'second sweep does not re-project when current' "$(if [ "$(wc -l < "$calls")" -eq 1 ] && [ "$PUSH_RC" -eq 0 ]; then echo 0; else echo 1; fi)"
check 'in-sync repos are not listed without --verbose' "$(if [[ $PUSH_OUT != *alpha:* && $PUSH_OUT == *'5 repos:'* ]]; then echo 0; else echo 1; fi)"
run
check 'bare status after a full push lists no repo, only the summary' "$(if [ "$(printf '%s\n' "$PUSH_OUT" | wc -l)" -eq 1 ] && [[ $PUSH_OUT == *'4 in sync'* ]]; then echo 0; else echo 1; fi)"
run --verbose
check '--verbose lists in-sync repos' "$(if [[ $PUSH_OUT == *'alpha: origin +0'* ]]; then echo 0; else echo 1; fi)"
commit "$root/code/pub" more
run --push
check 'new master commit makes the projection rebuild again' "$(if [ "$(wc -l < "$calls")" -eq 2 ]; then echo 0; else echo 1; fi)"

# 7 one failing repo does not stop the sweep; exit non-zero
git clone -q "$root/origins/alpha.git" "$root/other"
commit "$root/other" diverge
git -C "$root/other" push -q origin HEAD:master
commit "$root/code/alpha" local-only
commit "$root/code/legacy" fresh
run --push
check 'rejected repo is FAILED, sweep continues, exit non-zero' \
	"$(if [ "$PUSH_RC" -eq 1 ] && [[ $PUSH_OUT == *'alpha: FAILED'* ]] && [ "$(git -C "$root/code/legacy" rev-parse master)" = "$(git -C "$root/origins/legacy.git" rev-parse master)" ]; then echo 0; else echo 1; fi)"

# 8 a failed projection scan pushes nowhere (origin included)
commit "$root/code/pub" flagged
origin_before=$(git -C "$root/origins/pub.git" rev-parse master)
STUB_FAIL=1 run --push
check 'failed projection leaves origin untouched and marks the repo FAILED' \
	"$(if [ "$PUSH_RC" -eq 1 ] && [[ $PUSH_OUT == *'pub: FAILED'* ]] && [ "$(git -C "$root/origins/pub.git" rev-parse master)" = "$origin_before" ]; then echo 0; else echo 1; fi)"

# 9 pure helper
# shellcheck source=util/lib/push.sh
. "$helper"
j() { printf '{\n  "manifest": {"lagCommits": 9},\n  "projectedSource": %s,\n  "lagCommits": %s\n}\n' "$1" "$2"; }
p() { _push_parse_status "$(j "$1" "$2")"; }
res=
_push_needs_projection "$(p '"abc"' 0)" && res+=a
_push_needs_projection "$(p '"abc"' 2)" && res+=b
_push_needs_projection "$(p null null)" && res+=c
_push_needs_projection "$(p '"abc"' null)" && res+=d
_push_needs_projection "" && res+=e
check 'needs-projection only on lag, null lag, no projection or unavailable status' "$(if [ "$res" = bcde ]; then echo 0; else echo 1; fi)"

# 10 unparsable status: reported unavailable, never current, so --push projects
commit "$root/code/pub" garbled
STUB_GARBAGE=1 run
check 'unparsable status is reported as status unavailable' "$(if [[ $PUSH_OUT == *'pub: origin +'*'; projection status unavailable'* ]]; then echo 0; else echo 1; fi)"
before_calls=$(wc -l < "$calls")
STUB_GARBAGE=1 run --push
check 'unparsable status under --push projects instead of reading as current' \
	"$(if [[ $PUSH_OUT != *'pub: FAILED'* ]] && [ "$(wc -l < "$calls")" -eq $((before_calls + 1)) ] && [[ $PUSH_OUT == *'(projecting public)'* ]]; then echo 0; else echo 1; fi)"

# 11 --push reads publish.mjs status once per repo
commit "$root/code/pub" once
export STUB_STATUS_LOG="$root/status-calls"
: > "$STUB_STATUS_LOG"
run --push
check '--push reads publish.mjs status once up front, plus one re-read after a projection (release check)' \
	"$(if [[ $PUSH_OUT != *'pub: FAILED'* ]] && [ "$(wc -l < "$STUB_STATUS_LOG")" -eq 2 ] && [[ $PUSH_OUT == *'(projecting public)'* ]]; then echo 0; else echo 1; fi)"

# 12 a failed status call aborts the repo: FAILED, nothing pushed, no projection
commit "$root/code/pub" statusfail
origin_before=$(git -C "$root/origins/pub.git" rev-parse master)
before_calls=$(wc -l < "$calls")
: > "$STUB_STATUS_LOG"
STUB_STATUS_FAIL=1 run --push
check 'failed status call aborts the repo once, pushing and projecting nothing' \
	"$(if [[ $PUSH_OUT == *'pub: FAILED'* && $PUSH_OUT == *'(projection status failed; not pushing to github)'* && $PUSH_OUT == *'(not pushing to origin either'* ]] && [ "$(git -C "$root/origins/pub.git" rev-parse master)" = "$origin_before" ] && [ "$(wc -l < "$calls")" -eq "$before_calls" ] && [ "$(wc -l < "$STUB_STATUS_LOG")" -eq 1 ]; then echo 0; else echo 1; fi)"
unset STUB_STATUS_LOG

# 13 auto-release after the github leg (stubbed release; separate one-repo roots)
mkpub() { # <case>: fully pushed repo, zero lag, github mirror current
	local c="$root/c_$1" r="$root/c_$1/r"
	mkdir -p "$c"; git init -q -b master "$r"; : > "$r/INITIATIVE.md"
	git -C "$r" add -A; commit "$r" base
	git init -q --bare -b master "$root/o_$1.git"; git init -q --bare -b master "$root/g_$1.git"
	git -C "$r" remote add origin "$root/o_$1.git"; git -C "$r" remote add github "$root/g_$1.git"
	git -C "$r" config remote.github.push refs/heads/public:refs/heads/master
	echo '{}' > "$r/.publication.json"
	git -C "$r" push -q -u origin master
	git -C "$r" rev-parse master > "$r/.git/stub-projected"; git -C "$r" branch -f public master
	git -C "$r" push -q github public:master; git -C "$r" fetch -q github
}
runc() { local c=$1; shift; PUSH_OUT=$(bash "$script" --root "$root/c_$c" --publish-mjs "$root/publish-stub.sh" "$@" 2>&1); PUSH_RC=$?; }
rel_n() { wc -l < "$STUB_RELEASE_CALLS"; }

mkpub none
before_proj=$(wc -l < "$calls")
runc none --push
check 'no unreleased tags: release is never called' "$(if [ "$(rel_n)" -eq 0 ] && [ "$PUSH_RC" -eq 0 ]; then echo 0; else echo 1; fi)"

mkpub tagonly
before_proj=$(wc -l < "$calls")
STUB_UNPROJECTED=v1.0.0 runc tagonly
check 'bare mode lists an unprojected tag as pending and runs neither project nor release' \
	"$(if [[ $PUSH_OUT == *'unprojected tags: v1.0.0'* ]] && [ "$(rel_n)" -eq 0 ] && [ "$(wc -l < "$calls")" -eq "$before_proj" ]; then echo 0; else echo 1; fi)"
STUB_UNPROJECTED=v1.0.0 runc tagonly --push
check 'tag-only unprojected at zero lag projects, then releases once in the same run' \
	"$(if [ "$(wc -l < "$calls")" -eq $((before_proj + 1)) ] && [ "$(rel_n)" -eq 1 ] && [[ $PUSH_OUT == *'release: pushed (v1.0.0)'* ]] && [ "$PUSH_RC" -eq 0 ]; then echo 0; else echo 1; fi)"

mkpub unrel
before_proj=$(wc -l < "$calls"); before_rel=$(rel_n)
STUB_UNRELEASED=v2.0.0 runc unrel
check 'bare mode lists an unreleased tag as pending and runs neither project nor release' \
	"$(if [[ $PUSH_OUT == *'unreleased tags: v2.0.0'* && $PUSH_OUT == *'1 pending'* ]] && [ "$(rel_n)" -eq "$before_rel" ] && [ "$(wc -l < "$calls")" -eq "$before_proj" ]; then echo 0; else echo 1; fi)"
STUB_UNRELEASED=v2.0.0 runc unrel --push
check 'unreleased tag: exactly one release --push, no projection' \
	"$(if [ "$(rel_n)" -eq $((before_rel + 1)) ] && grep -q '^release --push --repo ' "$STUB_RELEASE_CALLS" && [ "$(wc -l < "$calls")" -eq "$before_proj" ]; then echo 0; else echo 1; fi)"
STUB_UNRELEASED=v2.0.0 runc unrel --push
check 'a recorded release is not released again' "$(if [ "$(rel_n)" -eq $((before_rel + 1)) ]; then echo 0; else echo 1; fi)"

mkpub fail
commit "$root/c_fail/r" newwork
before_rel=$(rel_n)
STUB_UNRELEASED=v3.0.0 STUB_RELEASE_FAIL=1 runc fail --push
check 'release failure keeps the branch pushes, is FAILED and counted in the summary' \
	"$(if [ "$PUSH_RC" -eq 1 ] && [[ $PUSH_OUT == *'FAILED (release;'* && $PUSH_OUT == *'release: failed (release: no GitHub token)'* && $PUSH_OUT == *'1 failed'* ]] && [ "$(git -C "$root/c_fail/r" rev-parse master)" = "$(git -C "$root/o_fail.git" rev-parse master)" ] && [ "$(git -C "$root/c_fail/r" rev-parse public)" = "$(git -C "$root/g_fail.git" rev-parse master)" ] && [ "$(rel_n)" -eq $((before_rel + 1)) ]; then echo 0; else echo 1; fi)"
mkpub rc5
( cd "$root/c_rc5/r" && publish_mjs="$root/publish-stub.sh" STUB_UNRELEASED=v3.0.0 STUB_RELEASE_FAIL=1 push_repo --branch master --when-lagging > /dev/null 2>&1 )
check 'push_repo returns the distinct release-failure code 5' "$(if [ $? -eq 5 ]; then echo 0; else echo 1; fi)"

printf '%d passed, %d failed\n' "$pass_count" "$fail_count"
[ "$fail_count" -eq 0 ]
